# Timer-driven loading bar: composited CSS keyframes, counter on the same clock. Delimiter ~.
# 1. CSS block
s~  /\* ---------- full-page loading screen \*/\n.*?  \@media \(prefers-reduced-motion:reduce\)\{\.sl-fill,\.sl-spill,\.site-loader,\.sl-head\{transition:none\}\}\n~  /* ---------- full-page loading screen: bar, glow and counter run as CSS animations on one fixed clock */\n  \@property --slp{syntax:'<integer>';inherits:false;initial-value:1}\n  .site-loader{--sl-dur:3s;position:fixed;inset:0;z-index:1000;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:36px;background-color:\#0A0A0C;background-image:radial-gradient(ellipse 70% 45% at 50% 26%,rgba(255,255,255,.045),transparent 70%),radial-gradient(ellipse 42% 22% at 50% 64%,rgba(0,255,102,.05),transparent 70%),radial-gradient(circle at 50% 50%,rgba(255,255,255,.035) 0 .8px,transparent 1.4px),radial-gradient(circle at 0 0,rgba(255,255,255,.028) 0 .8px,transparent 1.4px);background-size:100% 100%,100% 100%,6px 6px,6px 6px;background-position:0 0,0 0,0 0,3px 3px;transition:opacity .7s ease,visibility .7s;will-change:opacity;font-family:var(--body)}\n  .site-loader.out{opacity:0;visibility:hidden;pointer-events:none}\n  html.is-loading{overflow:hidden}\n  .sl-head{display:flex;flex-direction:column;align-items:center;gap:14px;opacity:0;transition:opacity .5s ease}\n  .site-loader.fonts .sl-head{opacity:1}\n  .sl-title{font-family:var(--wordmark);font-size:clamp(28px,4vw,44px);line-height:1;letter-spacing:.14em;padding-left:.14em;background:linear-gradient(180deg,\#F4F6F7 0%,\#C9CED3 48%,\#8D949B 100%);-webkit-background-clip:text;background-clip:text;color:transparent}\n  .sl-sub{font:600 10.5px/1 var(--body);letter-spacing:.32em;padding-left:.32em;text-transform:uppercase;color:\#6F7983;text-align:center}\n  .sl-row{display:flex;align-items:center;gap:16px}\n  .sl-frame{position:relative;width:min(340px,62vw);padding:3px;border-radius:7px;background:linear-gradient(180deg,\#2b2f34,\#15181b);box-shadow:inset 0 1px 0 rgba(255,255,255,.14),inset 0 -1px 0 rgba(0,0,0,.7),0 1px 0 rgba(255,255,255,.04),0 6px 18px rgba(0,0,0,.6)}\n  .sl-track{position:relative;height:6px;border-radius:4px;background:\#0b0d0f;box-shadow:inset 0 1px 2px rgba(0,0,0,.9);overflow:hidden}\n  .sl-fill{position:absolute;top:0;bottom:0;left:0;width:100%;border-radius:4px;background:linear-gradient(90deg,\#00C853,\#00FF66 60%,\#9CFFC2);box-shadow:0 0 10px rgba(0,255,102,.9);transform:translateX(-100%);animation:slFill var(--sl-dur) cubic-bezier(.22,.61,.36,1) forwards;will-change:transform}\n  .sl-glow{position:absolute;left:3px;right:3px;top:50%;height:64px;margin-top:-32px;pointer-events:none;background:radial-gradient(ellipse 18% 55% at 100% 50%,rgba(0,255,102,.6),rgba(0,255,102,.14) 45%,transparent 72%);filter:blur(7px);transform:translateX(-100%);animation:slFill var(--sl-dur) cubic-bezier(.22,.61,.36,1) forwards;will-change:transform}\n  \@keyframes slFill{from{transform:translateX(-100%)}to{transform:translateX(0)}}\n  .sl-pct{font:500 12px/1 var(--mono);color:\#8A939C;min-width:3.2em;font-variant-numeric:tabular-nums}\n  .sl-pct::after{content:counter(slpct) "%";counter-reset:slpct var(--slp);animation:slCount var(--sl-dur) cubic-bezier(.22,.61,.36,1) forwards}\n  .sl-pct.js-count::after{content:none}\n  \@keyframes slCount{from{--slp:1}to{--slp:100}}\n  .sl-label{position:absolute;bottom:36px;left:0;right:0;text-align:center;font:500 10.5px/1 var(--mono);letter-spacing:.18em;text-transform:uppercase;color:\#4E565D}\n  \@media (prefers-reduced-motion:reduce){.site-loader{--sl-dur:.8s}}\n~s;
# 2. markup
s~  <div class="sl-row"><div class="sl-frame"><div class="sl-track"><div class="sl-fill"></div></div><div class="sl-spill"></div></div><div class="sl-pct">4%</div></div>\n~  <div class="sl-row"><div class="sl-frame"><div class="sl-track"><div class="sl-fill"></div></div><div class="sl-glow"></div></div><div class="sl-pct" aria-hidden="true"></div></div>\n~;
# 3. controller
s~\(\(\) => \{\n  const el = document\.getElementById\('siteLoader'\); if \(!el\) return;.*?requestAnimationFrame\(tick\);\n\}\)\(\);~(() => {\n  const el = document.getElementById('siteLoader'); if (!el) return;\n  const fill = el.querySelector('.sl-fill'), pct = el.querySelector('.sl-pct'), lbl = el.querySelector('.sl-label');\n  const reduced = window.matchMedia \&\& window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n  const DUR = reduced ? 800 : 3000;\n  const t0 = performance.now();\n  let animDone = false, ready = false, finished = false, real = 0;\n  const finishCbs = [];\n  document.documentElement.classList.add('is-loading');\n  /* browsers without \@property count with a script on the same clock and easing */\n  if (!(window.CSS \&\& CSS.registerProperty)) {\n    pct.classList.add('js-count');\n    const ease = t => 1 - Math.pow(1 - t, 2.4);\n    const count = (now) => { const k = Math.min(1, (now - t0) / DUR); pct.textContent = Math.max(1, Math.round(1 + 99 * ease(k))) + '%'; if (k < 1 \&\& !finished) requestAnimationFrame(count); };\n    requestAnimationFrame(count);\n  }\n  const maybeFinish = () => {\n    if (finished \|\| !animDone \|\| !ready) return;\n    finished = true;\n    if (lbl) lbl.textContent = 'Ready';\n    setTimeout(() => { el.classList.add('out'); document.documentElement.classList.remove('is-loading'); setTimeout(() => { el.remove(); finishCbs.splice(0).forEach(cb => { try { cb(); } catch (e) {} }); }, 900); }, 250);\n  };\n  fill.addEventListener('animationend', () => { animDone = true; maybeFinish(); });\n  setTimeout(() => { animDone = true; maybeFinish(); }, DUR + 400);\n  window.__loading = {\n    set(f) { real = Math.max(real, f \|\| 0); },\n    done() { ready = true; maybeFinish(); },\n    onFinish(cb) { if (finished \&\& !document.getElementById('siteLoader')) cb(); else finishCbs.push(cb); },\n    _debug: { state: () => ({ animDone, ready, finished, real, elapsed: performance.now() - t0 }) }\n  };\n  window.__loading.fail = window.__loading.done;\n  if (document.fonts \&\& document.fonts.ready) document.fonts.ready.then(() => el.classList.add('fonts'));\n  setTimeout(() => el.classList.add('fonts'), 700);\n  setTimeout(() => { if (!ready \&\& real <= 0.3) { const sc = document.querySelector('.scene'); if (sc) sc.classList.add('nogl'); window.__loading.done(); } }, 12000);\n  setTimeout(() => window.__loading.done(), 30000);\n})();~s;
